// Helpers shared by the fixture generators: MoonBit literals, bit-exact
// doubles, a seeded RNG, and writing generated files.
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const root = join(dirname(fileURLToPath(import.meta.url)), "..");

/** A MoonBit string expression; long strings become concatenated literals
 * because the compiler limits the width of a single literal. */
export function str(s) {
  const chars = [...s];
  if (chars.length <= 2000) return lit(chars);
  const pieces = [];
  for (let i = 0; i < chars.length; i += 2000) pieces.push(lit(chars.slice(i, i + 2000)));
  return pieces.join(" +\n    ");
}

function lit(chars) {
  let out = '"';
  for (const ch of chars) {
    const c = ch.codePointAt(0);
    if (ch === "\\") out += "\\\\";
    else if (ch === '"') out += '\\"';
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (c < 0x20 || c === 0x7f || c === 0x2028 || c === 0x2029 || (c >= 0xd800 && c <= 0xdfff)) {
      out += `\\u{${c.toString(16)}}`;
    } else out += ch;
  }
  return out + '"';
}

const buf = new DataView(new ArrayBuffer(8));
export function hex(x) {
  buf.setFloat64(0, x);
  return buf.getBigUint64(0).toString(16).padStart(16, "0");
}

/** mulberry32: fixed-seed RNG so regenerating fixtures is reproducible. */
export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function writeGen(relPath, body) {
  const path = join(root, relPath);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `// Generated by scripts/gen_fixtures.mjs. Do not edit.\n\n${body}`);
  console.log(`wrote ${relPath}`);
}

export function strArray(name, items, { pub = true } = {}) {
  const lines = items.map((s) => `  ${str(s)},`).join("\n");
  return `///|\n${pub ? "pub " : ""}let ${name} : Array[String] = [\n${lines}\n]\n`;
}

/** Pairs of fixture scene cases, split so no generated file gets too large. */
export function sceneCases(name, cases) {
  const item = (c) =>
    `  { name: ${str(c.name)}, input: ${str(c.input)}, fonts: ${str(c.fonts)}, expected: ${c.expected === null ? "None" : `Some(${str(c.expected)})`} },`;
  return `///|\npub let ${name} : Array[SceneCase] = [\n${cases.map(item).join("\n")}\n]\n`;
}
